(() => {
  const rows = QueryLabDeptAsset1.data || [];
  // Group by Lab → Location
  const byLab = {};
  rows.forEach(r => {
    const labKey = String(r.Lab);
    if (!byLab[labKey]) byLab[labKey] = {};
    if (!byLab[labKey][r.Location]) byLab[labKey][r.Location] = [];
    byLab[labKey][r.Location].push({
      label: r.HardwareName,
      // leaf nodes carry the Hardware ID so we can filter precisely
      value: `hw:${r.ID}`
    });
  });

  // Build TreeSelect structure
  return Object.entries(byLab).map(([lab, locs]) => ({
    label: `Lab ${lab}`,
    value: `lab:${lab}`,
    children: Object.entries(locs).map(([loc, items]) => ({
      label: loc,
      value: `loc:${lab}:${loc}`,
      children: items
    }))
  }));
})()
}}
